.info-list dt:first-child {
  margin-top: 0;
}

.info-list dd {
  overflow-wrap: anywhere;
}

/* About */

.story {
  display: grid;
  grid-template-columns: 1fr 480px;
  gap: var(--space-7);
  align-items: center;
}

.story p + p {
  margin-top: var(--space-4);
}

.story-art {
  border-radius: var(--radius-lg);
}

.avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: var(--space-3);
  border-radius: 50%;
  background: var(--color-brand-tint);
  font-size: 18px;
  font-weight: 800;
  color: var(--color-brand-dark);
}

.timeline {
  padding-left: var(--space-5);
  border-left: 2px solid var(--color-line);
}

.timeline-item {
  position: relative;
  padding-bottom: var(--space-5);
}

.timeline-item:last-child {
  padding-bottom: 0;
}

.timeline-item::before {
  content: '';
  position: absolute;
  top: 5px;
  left: -32px;
  width: 12px;
  height: 12px;
  border: 2px solid var(--color-surface);
  border-radius: 50%;
  background: var(--color-brand);
}

.timeline-year {
  font-weight: 800;
  color: var(--color-brand);
}

.cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  padding: var(--space-6);
  border-radius: var(--radius-lg);
  background: var(--color-ink);
  color: #ffffff;
}

.cta p {
  margin-top: var(--space-1);
  color: #c9d1d9;
}

@media (max-width: 720px) {
  .hero {
    padding-top: var(--space-7);
  }

  .hero-inner,
  .feature,
  .newsletter,
  .bundles,
  .plans,
  .faq,
  .contact-grid,
  .story {
    grid-template-columns: 1fr;
  }

  .hero-copy h1 {
    font-size: 32px;
  }

  .feature-copy {
    padding: 0 var(--space-5) var(--space-5);
  }

  .feature-art {
    height: 160px;
  }

  .newsletter {
    padding: var(--space-5);
  }

  .cta {
    flex-direction: column;
    align-items: flex-start;
  }
}
  color: var(--color-muted);
}

.card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: var(--space-4);
}

.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-5);
}

.cards-4 {
  grid-template-columns: repeat(4, 1fr);
}

.badge {
  position: absolute;
  top: -10px;
  right: -10px;
  padding: 3px 10px;
  border-radius: var(--radius-pill);
  background: var(--color-brand);
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
}

.badge-sale {
  background: var(--color-danger);
}

.price {
  font-size: 20px;
  font-weight: 800;
  color: var(--color-brand);
}

/* Stat */

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.stat {
    background: var(--color-surface);
    border-bottom: 1px solid var(--color-line);
    box-shadow: var(--shadow-md);
  }

  .site-nav.is-open {
    display: flex;
  }

  .nav-link {
    padding: var(--space-3);
  }

  .cards,
  .cards-4,
  .stats {
    grid-template-columns: 1fr;
  }

  .footer-inner {
    flex-direction: column;
    align-items: flex-start;
  }
}

